/* ============================= WIDGETS ============================= */
function escapeHtml(s){
  return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}

/* -- Temperature / sampling -- */
const TEMP_VOCAB = [
  {tok:'sunny', logit:3.5}, {tok:'cloudy', logit:3.2}, {tok:'rainy', logit:2.8},
  {tok:'cold', logit:2.0}, {tok:'pleasant', logit:1.5}, {tok:'unusual', logit:0.5},
  {tok:'purple', logit:-1.0}, {tok:'banana', logit:-2.5}
];
function softmaxProbs(temp){
  const scaled = TEMP_VOCAB.map(v => v.logit/temp);
  const max = Math.max(...scaled);
  const exps = scaled.map(s => Math.exp(s-max));
  const sum = exps.reduce((a,b)=>a+b,0);
  return exps.map(e => e/sum);
}
function renderTempWidget(tempVal){
  const temp = parseFloat(tempVal);
  document.getElementById('temp-value').textContent = temp.toFixed(2);
  const probs = softmaxProbs(temp);
  const maxProb = Math.max(...probs);
  const barsHtml = TEMP_VOCAB.map((v,i) => {
    const pct = Math.round(probs[i]*1000)/10;
    const widthPct = (probs[i]/maxProb*100).toFixed(1);
    return `<div class="temp-bar-row"><span class="temp-bar-label">${v.tok}</span><div class="temp-bar-track"><div class="temp-bar-fill" style="width:${widthPct}%"></div></div><span class="temp-bar-pct">${pct}%</span></div>`;
  }).join('');
  document.getElementById('temp-bars').innerHTML = barsHtml;
}
function sampleTempWidget(){
  const temp = parseFloat(document.getElementById('temp-slider').value);
  const probs = softmaxProbs(temp);
  let r = Math.random(); let cum=0; let chosen = TEMP_VOCAB[TEMP_VOCAB.length-1].tok;
  for(let i=0;i<probs.length;i++){ cum+=probs[i]; if(r<=cum){chosen=TEMP_VOCAB[i].tok; break;} }
  document.getElementById('temp-sample-result').textContent = 'sampled: "' + chosen + '"';
}

/* -- Cosine similarity -- */
const COS_WORDS = {
  king:[0.9,0.6], queen:[0.85,0.65], man:[0.8,-0.3], woman:[0.75,-0.2],
  dog:[-0.6,0.7], puppy:[-0.55,0.75], cat:[-0.65,0.6],
  car:[-0.2,-0.8], truck:[-0.15,-0.85], banana:[0.1,-0.9], apple:[0.15,-0.85], happy:[0.3,0.9]
};
function cosineSim(a,b){
  const dot = a[0]*b[0]+a[1]*b[1];
  const magA = Math.hypot(a[0],a[1]);
  const magB = Math.hypot(b[0],b[1]);
  return dot/(magA*magB);
}
function renderCosWidget(){
  const wordA = document.getElementById('cos-a').value;
  const wordB = document.getElementById('cos-b').value;
  const vA = COS_WORDS[wordA]; const vB = COS_WORDS[wordB];
  const sim = cosineSim(vA,vB);
  const cx=100, cy=100, scale=80;
  const ax = cx + vA[0]*scale, ay = cy - vA[1]*scale;
  const bx = cx + vB[0]*scale, by = cy - vB[1]*scale;
  const svg = '<line x1="'+cx+'" y1="'+cy+'" x2="'+ax+'" y2="'+ay+'" stroke="#4FA69A" stroke-width="2"/>'+
    '<circle cx="'+ax+'" cy="'+ay+'" r="4" fill="#4FA69A"/>'+
    '<text x="'+ax+'" y="'+(ay-8)+'" font-family="IBM Plex Mono" font-size="10" fill="#4FA69A" text-anchor="middle">'+escapeHtml(wordA)+'</text>'+
    '<line x1="'+cx+'" y1="'+cy+'" x2="'+bx+'" y2="'+by+'" stroke="#E3A548" stroke-width="2"/>'+
    '<circle cx="'+bx+'" cy="'+by+'" r="4" fill="#E3A548"/>'+
    '<text x="'+bx+'" y="'+(by-8)+'" font-family="IBM Plex Mono" font-size="10" fill="#E3A548" text-anchor="middle">'+escapeHtml(wordB)+'</text>'+
    '<circle cx="'+cx+'" cy="'+cy+'" r="2" fill="#5A6270"/>';
  document.getElementById('cos-svg').innerHTML = svg;
  document.getElementById('cos-result').textContent = 'cosine similarity: ' + sim.toFixed(2);
}

/* -- Tokenizer playground -- */
const TOK_VOCAB = ['engineer','ization','retriev','believ','vector','search','straw','berry','token','agent','model','quick','brown','chain','learn','embed','graph','lazy','jump','ding','able','ness','ment','tion','over','play','test','post','lang','ning','pre','the','fox','dog','cat','run','un','er','ed','al','ic','ly','ing','s'].sort((a,b)=>b.length-a.length);
function tokenizeWord(word){
  let i=0; const tokens=[];
  while(i < word.length){
    let matched = null;
    for(const piece of TOK_VOCAB){
      if(word.startsWith(piece, i)){ matched = piece; break; }
    }
    if(matched){ tokens.push(matched); i += matched.length; }
    else { tokens.push(word[i]); i += 1; }
  }
  return tokens;
}
function renderTokWidget(){
  const raw = document.getElementById('tok-input').value.toLowerCase();
  const words = raw.split(/\s+/).filter(Boolean);
  let allTokens = [];
  words.forEach(w => { allTokens = allTokens.concat(tokenizeWord(w)); });
  const html = allTokens.map((t,i) => `<span class="tok-chip tok-chip-${i%4}">${escapeHtml(t)}</span>`).join('');
  document.getElementById('tok-output').innerHTML = html || '<span class="widget-hint">type something above</span>';
}

/* -- Chunking sandbox -- */
function chunkFixedText(text, size, overlap){
  const chunks = [];
  let start = 0;
  const step = Math.max(1, size - overlap);
  while(start < text.length){
    const end = Math.min(start+size, text.length);
    chunks.push(text.slice(start, end));
    if(end >= text.length) break;
    start += step;
  }
  return chunks;
}
function chunkRecursiveText(text, maxSize){
  const sentences = text.split(/(?<=[.!?])\s+/);
  const chunks = [];
  let current = '';
  sentences.forEach(sentence => {
    if(current.length + sentence.length + 1 > maxSize && current.length>0){
      chunks.push(current.trim());
      current = sentence;
    } else {
      current = current ? current + ' ' + sentence : sentence;
    }
  });
  if(current.trim()) chunks.push(current.trim());
  return chunks;
}
function renderChunkWidget(){
  const text = document.getElementById('chunk-text').value;
  const strategy = document.getElementById('chunk-strategy').value;
  const size = parseInt(document.getElementById('chunk-size').value,10);
  const overlap = parseInt(document.getElementById('chunk-overlap').value,10);
  document.getElementById('chunk-size-val').textContent = size;
  document.getElementById('chunk-overlap-val').textContent = overlap;
  let chunks;
  if(strategy === 'fixed'){
    chunks = chunkFixedText(text, size, Math.min(overlap, Math.max(0,size-1)));
  } else {
    chunks = chunkRecursiveText(text, size);
  }
  const html = chunks.map((c,i) => `<span class="chunk-${i%4}">${escapeHtml(c)}</span>`).join(strategy==='fixed' ? '' : ' ');
  document.getElementById('chunk-output').innerHTML = html;
  document.getElementById('chunk-count').textContent = chunks.length + ' chunk' + (chunks.length===1?'':'s') + (strategy==='fixed' ? ' · ' + overlap + ' char overlap' : ' · sentence-aware, no overlap');
  document.getElementById('chunk-overlap-row').style.opacity = strategy === 'fixed' ? '1' : '0.4';
}

/* -- RRF calculator -- */
const RRF_DOCS = ['Doc A','Doc B','Doc C','Doc D','Doc E','Doc F'];
const RRF_VECTOR_ORDER = ['Doc C','Doc A','Doc F','Doc B','Doc D','Doc E'];
const RRF_BM25_ORDER   = ['Doc B','Doc D','Doc A','Doc C','Doc E','Doc F'];
function renderRrfWidget(){
  const k = parseInt(document.getElementById('rrf-k').value,10);
  document.getElementById('rrf-k-val').textContent = k;
  const rows = RRF_DOCS.map(doc => {
    const vRank = RRF_VECTOR_ORDER.indexOf(doc)+1;
    const bRank = RRF_BM25_ORDER.indexOf(doc)+1;
    const score = 1/(k+vRank) + 1/(k+bRank);
    return {doc, vRank, bRank, score};
  });
  rows.sort((a,b)=>b.score-a.score);
  const html = '<table class="widget-table"><thead><tr><th>rank</th><th>document</th><th>vector rank</th><th>BM25 rank</th><th>fused score</th></tr></thead><tbody>' +
    rows.map((r,i)=>`<tr><td>${i+1}</td><td>${r.doc}</td><td>${r.vRank}</td><td>${r.bRank}</td><td>${r.score.toFixed(4)}</td></tr>`).join('') +
    '</tbody></table>';
  document.getElementById('rrf-table').innerHTML = html;
}

