/* -- RAG retrieval playground -- */
const RAG_DOCS = [
  {label:'Refund policy', x:30, y:40}, {label:'Shipping timelines', x:45, y:35},
  {label:'Password reset guide', x:140, y:120}, {label:'Two-factor auth setup', x:150, y:110},
  {label:'Product warranty terms', x:35, y:55}, {label:'API rate limits', x:160, y:40},
  {label:'Billing cycle FAQ', x:50, y:50}, {label:'Account deletion steps', x:145, y:130}
];
const RAG_QUERIES = [
  {label:'"How do I get my money back?"', x:38, y:45},
  {label:'"I forgot my login password"', x:145, y:115},
  {label:'"What are your API limits?"', x:158, y:45}
];
let ragSelectedIdx = null;
function ragDist(a,b){ return Math.hypot(a.x-b.x, a.y-b.y); }
function selectRagQuery(i){ ragSelectedIdx = i; renderRagWidget(); }
function renderRagWidget(){
  const btnHtml = RAG_QUERIES.map((q,i)=>`<button class="widget-btn ${i===ragSelectedIdx?'widget-btn-active':''}" onclick="selectRagQuery(${i})">${escapeHtml(q.label)}</button>`).join('');
  document.getElementById('rag-query-buttons').innerHTML = btnHtml;

  let ranked = [];
  let svgExtra = '';
  if(ragSelectedIdx !== null){
    const q = RAG_QUERIES[ragSelectedIdx];
    ranked = RAG_DOCS.map(d => ({label:d.label, x:d.x, y:d.y, d: ragDist(q,d)})).sort((a,b)=>a.d-b.d);
    const top2 = ranked.slice(0,2);
    svgExtra = top2.map(t => '<line x1="'+q.x+'" y1="'+q.y+'" x2="'+t.x+'" y2="'+t.y+'" stroke="#E3A548" stroke-width="1" stroke-dasharray="2,2"/>').join('') +
      '<circle cx="'+q.x+'" cy="'+q.y+'" r="5" fill="#E3A548"/><text x="'+q.x+'" y="'+(q.y-8)+'" font-family="IBM Plex Mono" font-size="8" fill="#E3A548" text-anchor="middle">query</text>';
  }
  const top2Labels = ranked.slice(0,2).map(t=>t.label);
  const docsHtml = RAG_DOCS.map(d => {
    const isTop = top2Labels.includes(d.label);
    const fill = isTop ? '#4FA69A' : '#5A6270';
    return '<circle cx="'+d.x+'" cy="'+d.y+'" r="4" fill="'+fill+'"/><text x="'+(d.x+6)+'" y="'+(d.y+3)+'" font-family="IBM Plex Sans" font-size="7.5" fill="'+(isTop?'#4FA69A':'#8D96A5')+'">'+escapeHtml(d.label)+'</text>';
  }).join('');
  document.getElementById('rag-svg').innerHTML = docsHtml + svgExtra;

  document.getElementById('rag-ranked').innerHTML = ragSelectedIdx===null ? '' :
    '<div class="section-label" style="margin-top:16px;">nearest to farthest</div>' + ranked.map((r,i)=>`<div>${i+1}. ${escapeHtml(r.label)} — distance ${r.d.toFixed(1)}</div>`).join('');
}

